<template>
 <div class="review-management"><header><div><h2>评审任务管理</h2><p>按评审任务查看专家、正式评语、历次修订和操作日志。</p></div><div class="actions"><DetailedExportButton domain="review-tasks" /><el-button @click="archiveTab=archiveTab==='rounds'?'legacy':'rounds'">{{archiveTab==='rounds'?'旧版历史意见':'返回评审任务'}}</el-button><el-button v-if="archiveTab==='rounds'" type="primary" @click="edit()">创建评审任务</el-button></div></header>
  <LegacyReviewArchive v-if="archiveTab==='legacy'"/><template v-else>
  <el-alert v-if="error" :title="error" type="error" :closable="false" /><el-button :loading="loading" @click="load">刷新</el-button>
  <el-table v-loading="loading" :data="rows" :empty-text="loading?'正在加载评审任务…':error?'加载失败，请重试':'尚未创建评审任务'"><el-table-column label="评审名称" min-width="260"><template #default="{row}"><el-button link type="primary" class="round-name" @click="manage(row,'overview')">{{row.name}}</el-button></template></el-table-column><el-table-column label="年度" width="110"><template #default="{row}">{{row.review_year||'全年度'}}</template></el-table-column><el-table-column label="评审时间" min-width="240"><template #default="{row}">{{time(row.startsAt)}}<br>{{time(row.endsAt)}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}">{{state(row.status)}}</template></el-table-column><el-table-column prop="memberCount" label="专家数" width="90"/><el-table-column label="操作" width="290"><template #default="{row}"><el-button link type="primary" @click="manage(row,'overview')">查看详情</el-button><el-button link @click="manage(row,'members')">管理专家与范围</el-button><el-button link @click="edit(row)">修改</el-button></template></el-table-column></el-table>
  </template>
  <el-dialog v-model="editVisible" :title="form.id?'修改评审任务':'创建评审任务'" width="min(640px,calc(100vw - 32px))" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy">
   <el-form label-position="top" :disabled="busy"><el-form-item label="评审名称"><el-input v-model="form.name" maxlength="120" placeholder="例如：2026年第一轮专家评审" /></el-form-item><el-form-item label="建设年度"><el-select v-model="form.year" :disabled="!!form.id"><el-option label="全年度（2025—2029）" :value="0"/><el-option v-for="y in years" :key="y" :label="`${y}年`" :value="y"/></el-select></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="form.startsAt" type="datetime" placeholder="选择开始时间" format="YYYY年MM月DD日 HH:mm" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="form.endsAt" type="datetime" placeholder="选择结束时间" format="YYYY年MM月DD日 HH:mm" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="评审说明"><el-input v-model="form.description" type="textarea" :rows="3" maxlength="2000"/></el-form-item><el-form-item v-if="form.id" label="修改原因"><el-input v-model="form.reason" maxlength="500"/></el-form-item></el-form><el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false"/>
   <template #footer><el-button :disabled="busy" @click="editVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveRound">保存</el-button></template>
  </el-dialog>
  <el-drawer v-model="manageVisible" title="评审详情" size="min(1280px,100vw)" :close-on-click-modal="false" :before-close="closeManage">
   <el-alert v-if="memberError" :title="memberError" type="error" :closable="false"/><div v-loading="detailLoading"><ReviewRoundReport v-if="current" :key="current.round_id" :round-id="current.round_id" :round-version="current.version" v-model:tab="detailTab" @round-read="syncRound"><template #members><el-steps :active="current.published?4:current.members?.length?2:1" finish-status="success" simple><el-step title="创建任务"/><el-step title="添加专家"/><el-step title="分配范围"/><el-step title="发布"/></el-steps><p>{{current.review_year||'全年度'}} · {{time(current.startsAt)}} 至 {{time(current.endsAt)}} · {{state(current.status)}}</p><p>{{current.description}}</p>
    <div class="actions"><el-button type="primary" :disabled="busy" @click="openMembers">添加专家</el-button><el-button :disabled="busy||!selected.length" @click="openScope(selected.map(m=>m.userId))">批量配置范围</el-button><el-button v-if="!current.published" type="success" :disabled="busy" @click="publish">核对并发布</el-button><el-button :disabled="busy" @click="detailTab='opinions'">查看正式评语</el-button></div>
    <el-alert v-if="memberError" :title="memberError" type="error" :closable="false"/>
    <el-table :data="current.members||[]" @selection-change="selected=$event"><el-table-column type="selection" width="45"/><el-table-column prop="name" label="专家"/><el-table-column prop="userId" label="账号"/><el-table-column prop="taskCount" label="已分配三级任务"/><el-table-column label="操作" min-width="170"><template #default="{row}"><el-button link :disabled="busy" @click="openScope([row.userId])">配置范围</el-button><el-button link type="danger" :disabled="busy" @click="remove(row)">移除</el-button></template></el-table-column></el-table><p>管理员无需个人授权即可在专家角色下评审全部任务。普通专家只能看到本轮分配的范围。</p>
   </template></ReviewRoundReport></div>
  </el-drawer>
  <el-dialog v-model="membersVisible" title="添加专家" width="min(720px,calc(100vw - 32px))" append-to-body :close-on-click-modal="false" :show-close="!busy">
   <div class="actions"><el-input v-model="keyword" placeholder="姓名或账号" @input="autoAccounts.schedule(true)" @keyup.enter="autoAccounts.flush()"/><el-button @click="accountVisible=true">新建专家账号</el-button></div>
   <el-table ref="accountTable" :data="accounts" v-loading="accountLoading" @selection-change="picked=$event" row-key="userId"><el-table-column type="selection" :selectable="r=>!current?.members?.some(m=>m.userId===r.userId)"/><el-table-column prop="name" label="姓名"/><el-table-column prop="userId" label="账号"/></el-table><el-pagination :current-page="accountPage" :page-size="50" :total="accountTotal" layout="prev,pager,next" @current-change="searchAccounts"/>
   <el-input v-model="memberReason" placeholder="添加原因（必填）" maxlength="500"/><el-alert v-if="memberError" :title="memberError" type="error" :closable="false"/>
   <template #footer><el-button :disabled="busy" @click="membersVisible=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!picked.length||!memberReason.trim()" @click="addMembers">添加并配置范围</el-button></template>
  </el-dialog>
  <el-dialog v-model="accountVisible" title="新建专家账号" width="min(480px,calc(100vw - 32px))" append-to-body :show-close="!busy" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="数字账号"><el-input v-model="account.userId" maxlength="15"/></el-form-item><el-form-item label="姓名"><el-input v-model="account.nickName" maxlength="100"/></el-form-item></el-form><p>初始密码为账号编号，首次登录必须修改密码。创建后尚无本轮任务权限。</p><el-alert v-if="accountError" :title="accountError" type="error" :closable="false"/><template #footer><el-button :disabled="busy" @click="accountVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="createAccount">创建</el-button></template></el-dialog>
  <el-dialog v-model="scopeVisible" title="配置本轮评审范围" width="min(800px,calc(100vw - 32px))" append-to-body :close-on-click-modal="false" :before-close="closeScope"><p>当前选择 {{scopeUsers.length}} 名专家。本次保存将统一替换其本轮范围，其他轮次及原业务职责保留。</p><el-input v-model="scopeKeyword" placeholder="搜索任务名称或编号"/><el-tree ref="scopeTree" :data="catalogTree" node-key="taskId" :props="{label:'label'}" show-checkbox :filter-node-method="filterNode" class="scope-tree"/><el-input v-model="scopeReason" maxlength="500" placeholder="范围调整原因（必填）"/><el-alert v-if="scopeError" :title="scopeError" type="error" :closable="false"/><template #footer><el-button :disabled="busy" @click="closeScope()">取消</el-button><el-button type="primary" :loading="busy" :disabled="!scopeReason.trim()" @click="saveScope">核对并保存范围</el-button></template></el-dialog>

 </div>
</template>
<script setup>
import DetailedExportButton from '../DetailedExportButton.vue'
import {ref,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {onBeforeRouteLeave,useRoute} from 'vue-router'
import ReviewRoundReport from './ReviewRoundReport.vue'
import LegacyReviewArchive from './LegacyReviewArchive.vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {get,post,put} from '@/utils/request'
import {createExpertAccount} from '@/api/permissions'
import {computed} from 'vue'
import {createFilterTrigger} from '@/utils/filterInteraction.mjs'
const route=useRoute(),archiveTab=ref(route.query.archive==='legacy'?'legacy':'rounds'),detailTab=ref('overview')
const base='/admin/review-tasks',years=[2025,2026,2027,2028,2029],rows=ref([]),loading=ref(false),busy=ref(false),error=ref(''),dialogError=ref(''),editVisible=ref(false),form=ref({}),current=ref(null),manageVisible=ref(false),detailLoading=ref(false),selected=ref([])
const accountTable=ref(null),membersVisible=ref(false),accounts=ref([]),accountLoading=ref(false),keyword=ref(''),picked=ref([]),accountPage=ref(1),accountTotal=ref(0),memberReason=ref(''),memberError=ref(''),accountVisible=ref(false),account=ref({userId:'',nickName:''}),accountError=ref('')
const scopeVisible=ref(false),scopeUsers=ref([]),catalog=ref([]),scopeTree=ref(null),scopeKeyword=ref(''),scopeReason=ref(''),scopeError=ref('')
let disposed=false,seq=0,accountSeq=0,detailSeq=0,scopeBaseline='',scopeLoading=false
const state=v=>({DRAFT:'草稿',UPCOMING:'未开始',ACTIVE:'进行中',ENDED:'已结束'})[v]||v
const time=v=>{if(!v)return '';const s=String(v).replace('T',' ').replace(/\.\d+(?:[+Z].*)?$/,'');const m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:\s+(\d{1,2}):(\d{1,2}))?/);if(!m)return s;const d=`${m[1]}年${Number(m[2])}月${Number(m[3])}日`;return m[4]?`${d} ${String(m[4]).padStart(2,'0')}:${String(m[5]).padStart(2,'0')}`:d}
// LocalDateTime omits zero seconds, while the date picker's value-format requires them.
const pickerTime=v=>String(v||'').replace(/(T\d{2}:\d{2})$/,'$1:00')
const catalogTree=computed(()=>{const nodes=new Map(catalog.value.map(t=>[t.taskId,{...t,label:`[${t.taskCode}] ${t.taskName}${t.level===3?`（${t.year}年）`:''}`,children:[]} ])),roots=[];for(const n of nodes.values()){const p=nodes.get(n.parentId);if(p)p.children.push(n);else roots.push(n)}return roots})
const filterNode=(term,data)=>!term||data.label.includes(term)
watch(scopeKeyword,k=>scopeTree.value?.filter(k))
async function load(){const n=++seq;loading.value=true;error.value='';try{const result=await get(base);if(!disposed&&n===seq)rows.value=result}catch(e){if(n===seq)error.value=e.message}finally{if(n===seq)loading.value=false}}
function edit(row){form.value=row?{id:row.round_id,name:row.name,year:row.review_year||0,startsAt:pickerTime(row.startsAt),endsAt:pickerTime(row.endsAt),description:row.description,version:row.version,reason:''}:{name:'',year:new Date().getFullYear(),startsAt:'',endsAt:'',description:''};dialogError.value='';editVisible.value=true}
async function saveRound(){if(busy.value)return;if(!form.value.name?.trim()||!form.value.startsAt||!form.value.endsAt||form.value.startsAt>=form.value.endsAt)return ElMessage.warning('请填写名称和正确的起止时间');if(form.value.id&&!form.value.reason?.trim())return ElMessage.warning('请填写修改原因');busy.value=true;dialogError.value='';try{const {id,...rest}=form.value;const b={...rest,year:form.value.year||null};const result=id?await put(`${base}/${id}`,b):await post(base,b);editVisible.value=false;await load();await manage(result,'members')}catch(e){dialogError.value=e.message}finally{busy.value=false}}
async function manage(row,tab='overview'){const n=++detailSeq;current.value=null;detailTab.value=tab;manageVisible.value=true;detailLoading.value=true;memberError.value='';try{const result=await get(`${base}/${row.round_id}`);if(!disposed&&n===detailSeq){current.value=result;selected.value=[]}}catch(e){memberError.value=e.message}finally{if(n===detailSeq)detailLoading.value=false}}
function syncRound(r){if(current.value?.round_id===r.round_id&&r.version>current.value.version){current.value=r;selected.value=[]}}
function openMembers(){picked.value=[];memberReason.value='';memberError.value='';membersVisible.value=true;searchAccounts(1)}
const autoAccounts=createFilterTrigger(()=>{if(membersVisible.value)return searchAccounts(1)})
async function searchAccounts(page){autoAccounts.cancel();const n=++accountSeq;accountLoading.value=true;try{const r=await get(`${base}/accounts`,{page,keyword:keyword.value});if(!disposed&&n===accountSeq){accounts.value=r.items;accountPage.value=r.page;accountTotal.value=r.total;picked.value=[]}}catch(e){memberError.value=e.message}finally{if(n===accountSeq)accountLoading.value=false}}
async function addMembers(){if(busy.value)return;busy.value=true;memberError.value='';const ids=picked.value.map(p=>p.userId);try{current.value=await post(`${base}/${current.value.round_id}/members`,{version:current.value.version,userIds:ids,reason:memberReason.value});membersVisible.value=false;await openScope(ids);await load()}catch(e){memberError.value=e.message}finally{busy.value=false}}
async function createAccount(){if(busy.value)return;if(!/^\d+$/.test(account.value.userId)||!account.value.nickName.trim())return ElMessage.warning('请填写数字账号和姓名');busy.value=true;accountError.value='';try{const result=await createExpertAccount({...account.value,userId:Number(account.value.userId),configureTasks:true});accountVisible.value=false;keyword.value=String(result.userId);await searchAccounts(1);await nextTick();for(const row of accounts.value.filter(a=>a.userId===result.userId))accountTable.value?.toggleRowSelection(row,true);ElMessage.success('账号已创建，请继续添加到本轮并配置范围')}catch(e){accountError.value=e.message}finally{busy.value=false}}
async function openScope(users){scopeLoading=true;scopeUsers.value=users;scopeKeyword.value='';scopeReason.value='';scopeError.value='';try{catalog.value=await get(`${base}/${current.value.round_id}/catalog`);const checked=users.length===1?await get(`${base}/${current.value.round_id}/members/${users[0]}/scope`):[];scopeVisible.value=true;await nextTick();scopeTree.value?.setCheckedKeys(checked);scopeBaseline=JSON.stringify(checked.slice().sort((a,b)=>a-b))}catch(e){memberError.value=e.message}finally{scopeLoading=false}}
const checkedIds=()=>scopeTree.value?.getCheckedNodes(false).filter(n=>n.level===3).map(n=>n.taskId).sort((a,b)=>a-b)||[]
async function closeScope(done){if(busy.value)return false;if(JSON.stringify(checkedIds())!==scopeBaseline||scopeReason.value.trim())try{await ElMessageBox.confirm('评审范围尚未保存，是否放弃修改？','离开确认',{confirmButtonText:'放弃修改',cancelButtonText:'继续配置'})}catch{return false}scopeVisible.value=false;done?.();return true}
async function closeManage(done){if(busy.value||scopeLoading)return;if(scopeVisible.value&&!await closeScope())return;manageVisible.value=false;current.value=null;detailLoading.value=false;detailSeq++;done?.()}
async function saveScope(){if(busy.value)return;busy.value=true;scopeError.value='';try{const ids=checkedIds();await ElMessageBox.confirm(`将把${scopeUsers.value.length}名专家的本轮范围设置为${ids.length}条三级任务。是否保存？`,'核对范围',{confirmButtonText:'确认保存',cancelButtonText:'返回修改'});current.value=await put(`${base}/${current.value.round_id}/scope`,{version:current.value.version,userIds:scopeUsers.value,taskIds:ids,reason:scopeReason.value});scopeVisible.value=false;ElMessage.success('本轮范围已保存');await load()}catch(e){if(e!=='cancel'&&e!=='close')scopeError.value=e.message}finally{busy.value=false}}
async function publish(){if(busy.value)return;busy.value=true;memberError.value='';try{await ElMessageBox.confirm('请确认评审时间、专家和任务范围。发布且到达开始时间后，普通专家才可开展评审。','发布确认',{confirmButtonText:'确认发布',cancelButtonText:'返回核对'});current.value=await post(`${base}/${current.value.round_id}/publish`,{version:current.value.version,reason:'核对时间、专家和范围后发布'});await load()}catch(e){if(e!=='cancel'&&e!=='close')memberError.value=e.message}finally{busy.value=false}}
async function remove(row){if(busy.value)return;busy.value=true;try{const {value}=await ElMessageBox.prompt(`移除${row.name}后立即收回本轮访问权限，已提交意见保留。请输入原因。`,'移除专家',{inputValidator:v=>!!v?.trim()||'请填写原因'});current.value=await post(`${base}/${current.value.round_id}/members/${row.userId}/remove`,{version:current.value.version,reason:value});await load()}catch(e){if(e!=='cancel'&&e!=='close')memberError.value=e.message}finally{busy.value=false}}

onBeforeRouteLeave(async()=>!busy.value&&(!scopeVisible.value||await closeScope()));onMounted(load);onUnmounted(()=>{autoAccounts.cancel();disposed=true;seq++;accountSeq++;detailSeq++})
</script>
<style scoped>.review-management{height:100%;overflow:auto;padding:24px;box-sizing:border-box;background:#f3f6fa}.review-management header{display:flex;justify-content:space-between;gap:16px;align-items:center}.round-name{white-space:normal;text-align:left;line-height:1.6;height:auto}.review-management h2{margin:0 0 8px}.review-management p{color:#738196;line-height:1.7}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.actions .el-input{width:220px}.scope-tree{max-height:48vh;overflow:auto;margin:12px 0}.review-management :deep(.el-dialog__body){max-height:70dvh;overflow:auto}.review-management :deep(.el-tree-node__label){white-space:normal;overflow-wrap:anywhere}.review-management :deep(.el-tree-node__content){height:auto;min-height:30px}</style>
